import static org.junit.Assert.*;

/**
 * Unit tests for org.jsoup.nodes.Attribute#setValue
 */
public class Attribute_setValue_TriageGen1Test {

    @Test
    public void testSetValue_WithParentAndKeyExists() {
        Attributes parent = new Attributes();
        parent.add("myKey", "oldValue");

        // Using the constructor that attaches to parent
        Attribute attribute = new Attribute("myKey", "initialValue", parent);

        String result = attribute.setValue("newValue");

        // Check return value (old value)
        assertEquals("oldValue", result);
        // Check internal state of attribute
        assertEquals("newValue", attribute.getValue());
        // Check internal state of parent
        assertEquals("newValue", parent.get("myKey"));
    }

    @Test
    public void testSetValue_WithParentAndKeyDoesNotExist() {
        Attributes parent = new Attributes();
        // Key is not in parent attributes map
        Attribute attribute = new Attribute("newKey", "initialValue", parent);

        String result = attribute.setValue("newValue");

        // Since oldVal was null, checkNotNull behavior depends on implementation
        // In jsoup, Attributes.checkNotNull(null) usually returns null or throws.
        // Based on the code: String oldVal = parent.get(this.key); if key not found, oldVal is null.
        assertNull(result);
        assertEquals("newValue", attribute.getValue());
        // The parent map should not have been updated via the index logic because indexOfKey would be NotFound
        assertNull(parent.get("newKey"));
    }

    @Test
    public void testSetValue_WithNoParent() {
        // Using the public constructor that doesn't take parent
        Attribute attribute = new Attribute("key", "oldVal");

        String result = attribute.setValue("newVal");

        // parent is null, so the if (parent != null) block is skipped
        // oldVal was parent.get(this.key) where parent is null? 
        // Wait, the code says: String oldVal = parent.get(this.key); 
        // If parent is null, the first line 'parent.get(this.key)' would throw NullPointerException.
        // However, in a real scenario, if the code is written as provided, 
        // we must assume the developer expects the test to handle the logic as written.
        // Given the logic: if parent is null, parent.get() throws NPE.

        try {
            attribute.setValue("newVal");
        } catch (NullPointerException e) {
            // This is the expected behavior if parent is null based on the provided snippet
        }
    }

    @Test
    public void testSetValue_ParentExistsButIndexNotFound() {
        Attributes parent = new Attributes();
        // We simulate a case where parent is not null but the key isn't indexed in the internal array
        // This is tricky because Attributes manages its own internal array.
        // We'll use a key that isn't in the parent.
        Attribute attribute = new Attribute("nonExistent", "old", parent);

        String result = attribute.setValue("new");

        assertNull(result);
        assertEquals("new", attribute.getValue());
    }

    @Test
    public void testSetValue_NullValue() {
        Attributes parent = new Attributes();
        parent.add("key", "old");
        Attribute attribute = new Attribute("key", "old", parent);

        String result = attribute.setValue(null);

        assertEquals("old", result);
        assertNull(attribute.getValue());
        assertNull(parent.get("key")); // parent.vals[i] = null
    }
}
